export function renderProjects(projects, error = '', filter = 'Active') {
  return page('Projects', `
    <h1>Workboard</h1>
    <section class="panel" aria-label="Create a project">
      <form method="post" action="/projects?filter=${filter}">
        <label for="project-name">Project name</label>
        <div class="create">
          <input id="project-name" name="name" type="text" autocomplete="off"${error ? ' aria-invalid="true" aria-describedby="name-error"' : ''}>
          <button type="submit">Create project</button>
        </div>
        ${error ? `<p id="name-error" role="alert">${escapeHtml(error)}</p>` : ''}
      </form>
    </section>
    <h2>Projects</h2>
    <form method="get" action="/">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['Active', 'Archived'].map(value => `<option${filter === value ? ' selected' : ''}>${value}</option>`).join('')}
      </select>
    </form>
    ${projects.length ? `<ul>${projects.map(project => `
      <li class="panel project" data-testid="project-row">
        <span>${escapeHtml(project.name)}</span>
        <span data-testid="project-summary">${project.completed}/${project.total} completed</span>
        <form method="get" action="/projects/${project.id}">
          <button type="submit">Open project</button>
        </form>
        <form method="post" action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}">
          <button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
        </form>
      </li>`).join('')}</ul>` : '<p class="empty">No projects yet.</p>'}
  `);
}

export function renderProject(project, tasks = [], filter = 'All', error = '', renameError = '', taskRenameError = null, priorityFilter = 'All') {
  const query = `filter=${filter}&amp;priorityFilter=${priorityFilter}`;
  return page(project.name, `
    <form method="get" action="/"><button type="submit">Projects</button></form>
    <h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <section class="panel" aria-label="Rename a project">
      <form method="post" action="/projects/${project.id}/rename?${query}">
        <label for="new-project-name">New project name</label>
        <div class="create">
          <input id="new-project-name" name="name" type="text" value="${escapeHtml(project.name)}"${project.archived ? ' disabled' : ''}${renameError ? ' aria-invalid="true" aria-describedby="rename-error"' : ''}>
          <button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button>
        </div>
        ${renameError ? `<p id="rename-error" role="alert">${escapeHtml(renameError)}</p>` : ''}
      </form>
    </section>
    <section class="panel" aria-label="Create a task">
      <form method="post" action="/projects/${project.id}/default-priority?${query}">
        <label for="default-task-priority">Default task priority</label>
        <select id="default-task-priority" name="priority"${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
          ${['Low', 'Normal', 'High'].map(value => `<option${project.default_priority === value ? ' selected' : ''}>${value}</option>`).join('')}
        </select>
      </form>
      <form method="post" action="/projects/${project.id}/tasks?${query}">
        <label for="task-title">Task title</label>
        <div class="create">
          <input id="task-title" name="title" type="text" autocomplete="off"${error ? ' aria-invalid="true" aria-describedby="task-error"' : ''}>
          <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button>
        </div>
        ${error ? `<p id="task-error" role="alert">${escapeHtml(error)}</p>` : ''}
      </form>
    </section>
    <h2>Tasks</h2>
    <form method="get" action="/projects/${project.id}">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['All', 'Open', 'Completed'].map(value => `<option${filter === value ? ' selected' : ''}>${value}</option>`).join('')}
      </select>
      <label for="priority-filter">Priority filter</label>
      <select id="priority-filter" name="priorityFilter" onchange="this.form.requestSubmit()">
        ${['All', 'Low', 'Normal', 'High'].map(value => `<option${priorityFilter === value ? ' selected' : ''}>${value}</option>`).join('')}
      </select>
    </form>
    ${tasks.length ? `<ul>${tasks.map(task => `
      <li class="panel task" data-testid="task-row">
        <form method="post" action="/projects/${project.id}/tasks/${task.id}?${query}">
          <label>
            <input type="checkbox" name="completed" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
            <span>${escapeHtml(task.title)}</span>
          </label>
        </form>
        <form method="post" action="/projects/${project.id}/tasks/${task.id}/priority?${query}">
          <label for="task-priority-${task.id}">Task priority</label>
          <select id="task-priority-${task.id}" name="priority"${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
            ${['Low', 'Normal', 'High'].map(value => `<option${task.priority === value ? ' selected' : ''}>${value}</option>`).join('')}
          </select>
        </form>
        <form method="post" action="/projects/${project.id}/tasks/${task.id}/rename?${query}">
          <label for="new-task-title-${task.id}">New task title</label>
          <div class="create">
            <input id="new-task-title-${task.id}" name="title" type="text" value="${escapeHtml(task.title)}"${project.archived ? ' disabled' : ''}${taskRenameError?.id === task.id ? ` aria-invalid="true" aria-describedby="task-rename-error-${task.id}"` : ''}>
            <button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button>
          </div>
          ${taskRenameError?.id === task.id ? `<p id="task-rename-error-${task.id}" role="alert">${escapeHtml(taskRenameError.message)}</p>` : ''}
        </form>
      </li>`).join('')}</ul>` : '<p class="empty">No matching tasks.</p>'}
  `);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

test('project defaults migrate, persist independently, and affect only new tasks', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-defaults-'));
  const dbPath = join(directory, 'db.sqlite');
  const db = new DatabaseSync(dbPath);
  db.exec(`CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0);
    INSERT INTO projects (name) VALUES ('Legacy');
    INSERT INTO tasks (project_id, title, completed) VALUES (1, 'Existing', 1);`);
  db.close();
  let child;
  let base;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: '0', DB_PATH: dbPath }, stdio: ['ignore', 'pipe', 'pipe'],
    });
    base = await new Promise((resolve, reject) => {
      child.once('error', reject);
      child.once('exit', code => reject(new Error(`Unexpected exit ${code}`)));
      child.stdout.on('data', chunk => {
        const match = /listening on port (\d+)/.exec(String(chunk));
        if (match) resolve(`http://127.0.0.1:${match[1]}`);
      });
    });
  }
  async function stop() {
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
    child = null;
  }
  const post = (path, data = {}) => fetch(base + path, {
    method: 'POST', body: new URLSearchParams(data), redirect: 'manual',
  });
  const page = async path => (await fetch(base + path)).text();
  const select = (html, id) => html.match(new RegExp(`<select id="${id}"[^>]*>[\\s\\S]*?<\\/select>`))[0];
  const selected = (html, id, value) => assert.match(select(html, id), new RegExp(`<option selected>${value}<`));
  const titles = html => [...html.matchAll(/aria-label="Complete ([^"]+)"/g)].map(match => match[1]);
  try {
    await start();
    let html = await page('/projects/1');
    selected(html, 'default-task-priority', 'Normal');
    selected(html, 'task-priority-1', 'Normal');
    assert.match(select(html, 'default-task-priority'), /<option>Low<\/option><option selected>Normal<\/option><option>High<\/option>/);
    await post('/projects', { name: 'Independent' });
    selected(await page('/projects/2'), 'default-task-priority', 'Normal');
    const query = '?filter=Completed&priorityFilter=Normal';
    const response = await post('/projects/1/default-priority' + query, { priority: 'High' });
    assert.equal(response.status, 303);
    assert.equal(response.headers.get('location'), '/projects/1' + query);
    html = await page(response.headers.get('location'));
    selected(html, 'task-filter', 'Completed');
    selected(html, 'priority-filter', 'Normal');
    selected(html, 'default-task-priority', 'High');
    assert.deepEqual(titles(html), ['Existing']);
    assert.match(html, /default-priority\?filter=Completed&amp;priorityFilter=Normal/);
    await post('/projects/1/tasks', { title: 'Inherited high' });
    await post('/projects/2/tasks', { title: 'Other normal' });
    await post('/projects/1/default-priority', { priority: 'Low' });
    await post('/projects/1/tasks', { title: 'Inherited low' });
    html = await page('/projects/1');
    assert.deepEqual(titles(html), ['Existing', 'Inherited high', 'Inherited low']);
    selected(html, 'task-priority-1', 'Normal');
    selected(html, 'task-priority-2', 'High');
    selected(html, 'task-priority-4', 'Low');
    selected(await page('/projects/2'), 'task-priority-3', 'Normal');
    await post('/projects/1/tasks/2/rename', { title: 'Renamed high' });
    await post('/projects/1/rename', { name: 'Renamed project' });
    assert.equal((await post('/projects/1/default-priority', { priority: 'Invalid' })).status, 400);
    selected(await page('/projects/1'), 'default-task-priority', 'Low');
    assert.match(await page('/'), /1\/3 completed/);
    await post('/projects/1/archive');
    html = await page('/projects/1' + query);
    assert.match(select(html, 'default-task-priority'), / disabled/);
    selected(html, 'default-task-priority', 'Low');
    assert.doesNotMatch(select(html, 'task-filter'), /disabled/);
    assert.doesNotMatch(select(html, 'priority-filter'), /disabled/);
    assert.equal((await post('/projects/1/default-priority', { priority: 'High' })).status, 403);
    await stop();
    await start();
    html = await page('/projects/1');
    selected(html, 'default-task-priority', 'Low');
    selected(html, 'task-priority-2', 'High');
    assert.match(html, /<h1>Renamed project<\/h1>/);
    assert.match(html, /aria-label="Complete Existing" checked/);
    await post('/projects/1/restore');
    html = await page('/projects/1');
